/**
 * For the #WCCChallenge
 * Genuary 16: Order and disorder.
 * Title: Random Walkers and Geometric Patterns
 * * Interaction:
 * - Click to toggle.
 * - Disorder: White lines move independently using Perlin noise (Flow Field).
 * - Order: Particles rush to the center to form geometric Patterns.
 */

let particles = [];
let numParticles = 1000; 
let gridSize = 30;

let isOrdered = false;
let patternType = 0; // 0: Spiral, 1: NoiseRing, 2: Rose
let baseHue = 0;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 100);
  background(0);

  for (let i = 0; i < numParticles; i++) {
    particles.push(new Particle(i));
  }

  noiseDetail(2, 0.5);
}

function draw() {
  noStroke();
  fill(0, 0, 0, 15); 
  rect(0, 0, width, height);

  for (let p of particles) {
    p.update(isOrdered);
    p.display(isOrdered);
  }
}

function mousePressed() {
  isOrdered = !isOrdered;

  if (isOrdered) {
    patternType = floor(random(3)); 
    baseHue = random(360);
    assignTargets();

  } else {
    for (let p of particles) {
      p.scatter();
    }
  }
}

function assignTargets() {
  let scaleFactor = (max(width, height) / 2) * 0.85; 

  for (let i = 0; i < numParticles; i++) {
    let p = particles[i];
    let tx, ty;

    if (patternType === 0) {
      let angle = i * 137.5; 
      let r = 5 * sqrt(i); 
      let maxR = 5 * sqrt(numParticles);
      r = map(r, 0, maxR, 0, scaleFactor);
      tx = r * cos(radians(angle));
      ty = r * sin(radians(angle));

    } else if (patternType === 1) {
      let angle = map(i, 0, numParticles, 0, TWO_PI * 5);
      let rBase = map(i, 0, numParticles, 50, scaleFactor);
      let rNoise = map(noise(angle * 3, millis()), 0, 1, -50, 50);
      tx = (rBase + rNoise) * cos(angle);
      ty = (rBase + rNoise) * sin(angle);

    } else {
      let k = floor(random(3, 9)); 
      let angle = map(i, 0, numParticles, 0, TWO_PI * 12);
      let r = scaleFactor * cos(k * angle) * map(i, 0, numParticles, 0.4, 1);
      tx = r * cos(angle);
      ty = r * sin(angle);
    }

    p.target.set(tx + width/2, ty + height/2);
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  background(0);
}

class Particle {
  constructor(index) {
    this.index = index;
    this.pos = createVector(random(width), random(height));
    this.prevPos = this.pos.copy(); 

    this.vel = p5.Vector.random2D();
    this.acc = createVector(0, 0);
    this.maxSpeed = 5;   //Changing this part makes it interesting.
    //this.maxSpeed = 12;  

    this.target = createVector(width/2, height/2);

    this.offset = random(1000); 
    this.colorOffset = random(60);
  }

  update(ordered) {
    this.prevPos.set(this.pos);

    if (!ordered) {
      let n = noise(this.pos.x * 0.01, this.pos.y * 0.01, frameCount * 0.01 + this.offset);
      let angle = map(n, 0, 1, 0, TWO_PI * 2);
      let force = p5.Vector.fromAngle(angle);
      force.mult(0.5);

      this.acc.add(force);
      this.vel.add(this.acc);
      this.vel.limit(this.maxSpeed);
      this.pos.add(this.vel);
      this.acc.mult(0); 

      this.edges();

    } else {
      this.pos.x = lerp(this.pos.x, this.target.x, 0.08);
      this.pos.y = lerp(this.pos.y, this.target.y, 0.08);
    }
  }

  display(ordered) {
    if (!ordered) {
      stroke(0, 0, 100, 60); 
      strokeWeight(1.5);
      line(this.prevPos.x, this.prevPos.y, this.pos.x, this.pos.y);

    } else {
      let d = dist(this.pos.x, this.pos.y, width/2, height/2);
      let h = (baseHue + map(d, 0, height/2, 0, 120) + this.colorOffset) % 360;

      noStroke();
      fill(h, 80, 100, 80); 
      circle(this.pos.x, this.pos.y, 3);
    }
  }

  scatter() {
    let vx = random(-this.maxSpeed, this.maxSpeed); 
    let vy = random(-3, 3);   

    this.vel = createVector(vx, vy);
  }

  edges() {
    let warped = false;
    if (this.pos.x > width) { this.pos.x = 0; warped = true; }
    if (this.pos.x < 0) { this.pos.x = width; warped = true; }
    if (this.pos.y > height) { this.pos.y = 0; warped = true; }
    if (this.pos.y < 0) { this.pos.y = height; warped = true; }

    if (warped) {
      this.prevPos.set(this.pos);
    }
  }
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
